class SORTracker { static class Place{String name;int score;Place(String name,int score){this.name=name;this.score=score;}}Comparator<Place> better=(a,b)->a.score!=b.score?b.score-a.score:a.name.compareTo(b.name);Comparator<Place> worse=(a,b)->a.score!=b.score?a.score-b.score:b.name.compareTo(a.name);PriorityQueue<Place> selected=new PriorityQueue<>(worse),remaining=new PriorityQueue<>(better);public SORTracker(){}public void add(String name,int score){remaining.offer(new Place(name,score));if(!selected.isEmpty()&&better.compare(remaining.peek(),selected.peek())<0){Place best=remaining.poll(),worst=selected.poll();remaining.offer(worst);selected.offer(best);}}public String get(){Place next=remaining.poll();selected.offer(next);return next.name;} }
